import json

input_text = """7 7 3 2 7 7 7 2 7 6 7 2 7 7 7 2 7 7 7
7 7 7 2 7 3 7 2 7 3 7 2 7 3 7 2 7 3 3
2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2
7 7 7 2 7 7 3 2 3 7 7 2 3 7 7 2 7 7 3
7 3 7 2 7 3 7 2 7 7 7 2 7 7 7 2 7 7 7
2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2
7 3 7 2 7 7 7 2 3 7 7 2 7 3 7 2 7 7 7
7 7 7 2 7 7 3 2 7 7 3 2 7 7 7 2 7 3 7"""

input_grid = []
for line in input_text.strip().split('\n'):
    row = [int(x) for x in line.split()]
    input_grid.append(row)

# Build output: 3 cell rows × 5 cell cols = 15 cells
# Check each cell for stray colors (non-7)
# Cells with strays → 8, else → 7

output = [[7]*5 for _ in range(3)]

def has_stray(r_cell, c_cell):
    """Check if cell at (r_cell, c_cell) has any non-7 value"""
    for dr in range(3):
        for dc in range(3):
            ir, ic = r_cell * 3 + dr, c_cell * 3 + dc
            if ir < len(input_grid) and ic < len(input_grid[0]):
                if input_grid[ir][ic] != 7:
                    return True
    return False

print("Cells with stray colors:")
for r_cell in range(3):
    for c_cell in range(5):
        if has_stray(r_cell, c_cell):
            print(f"  ({r_cell},{c_cell})")
            # Debug: print what values are in this cell
            for dr in range(3):
                for dc in range(3):
                    ir, ic = r_cell * 3 + dr, c_cell * 3 + dc
                    if ir < len(input_grid):
                        val = input_grid[ir][ic]
                        if val != 7:
                            print(f"    local ({dr},{dc}): {val}")
            output[r_cell][c_cell] = 8
            for dr in range(3):
                for dc in range(3):
                    ic = c_cell * 3 + dc
                    if input_grid[r_cell * 3 + dr][ic] != 7:
                        print(f"      Input: ({r_cell * 3 + dr},{ic}) = {input_grid[r_cell * 3 + dr][ic]}")
            for dr in range(3):
                for dc in range(3):
                    ic = c_cell * 3 + dc
                    if input_grid[r_cell * 3 + dr][ic] != 7:
                        print(f"      Input: ({r_cell * 3 + dr},{ic}) = {input_grid[r_cell * 3 + dr][ic]}")

print(f"\nFinal output grid: {output}")
print(f"Grid shape: {len(output)}×{len(output[0])}")

result = {"action": "submit", "grid": output}
print(json.dumps(result))

